// === Tab: Salidtude Viewer ===

// sketch.js
// The Agreement — Live Editor (OpenProcessing)
// Programmed by Owaun Scantlebury
//
// The same simulation + a live GLSL neighbourhood editor panel.
// Click any preset button to load it into the editor.
// Paste your own neighbourhood block that produces float lap.
// Auto-compiles 900ms after you stop typing.
// Ctrl+Enter to force compile immediately.
//
// CONTROLS
//   Mouse move    — directional bow wave
//   Mouse hold    — strong symmetric splash
//   1–6           — switch preset
//   [ ]           — c2 down / up
//   r             — reset field
//   s             — save PNG

// ═══════════════════════════════════════════════════════════════
// CONFIG
// ═══════════════════════════════════════════════════════════════
const SIM_W      = 920;
const SIM_H      = 690;
const NUM_LAYERS = 8;
const DISPLAY_W  = 920;
const DISPLAY_H  = 690;

const LAYER_DEPTH    = [0.00, 0.14, 0.28, 0.42, 0.57, 0.71, 0.85, 1.00];
const LAYER_COUPLING = [0.00, 0.18, 0.14, 0.10, 0.07, 0.05, 0.03, 0.02];
const LAYER_DAMPING  = [0.997, 0.996, 0.995, 0.994, 0.993, 0.992, 0.991, 0.990];
const LAYER_AMBIENT  = [0.001, 0.002, 0.003, 0.004, 0.005, 0.006, 0.007, 0.008];

let activeVariantKey = 'FOUR_POINT';
let PARAMS = { c2: 0.25, resistance: 6.0, ambient: 1.0, coupling: 1.0 };

// ═══════════════════════════════════════════════════════════════
// STATE
// ═══════════════════════════════════════════════════════════════
let physShader, displayShader;
let buffers = [];
let frameCount_ = 0;
let pmouseUV = { x: 0, y: 0 };
let mouseVelX = 0, mouseVelY = 0, mouseSpeed = 0;
let editorTA, statusEl, errEl, autoTimer;

// ═══════════════════════════════════════════════════════════════
// PRELOAD
// ═══════════════════════════════════════════════════════════════

function preload() {
	font = loadFont('https://openprocessing.org/sketch/2961620/files/TitilliumWeb-SemiBold.ttf')
}

// ═══════════════════════════════════════════════════════════════
// SETUP
// ═══════════════════════════════════════════════════════════════
function setup() {
  const cnv = createCanvas(DISPLAY_W, DISPLAY_H, WEBGL);
  cnv.style('display', 'block');
  textFont(font);
  noStroke();

  rebuildPhysicsShader();
  displayShader = createShader(VERT_SRC, DISPLAY_FRAG);

  for (let i = 0; i < NUM_LAYERS; i++) {
    buffers.push({
      a: createFramebuffer({ width: SIM_W, height: SIM_H, format: UNSIGNED_BYTE }),
      b: createFramebuffer({ width: SIM_W, height: SIM_H, format: UNSIGNED_BYTE }),
      which: 0
    });
  }

  seedAll();
  buildUI();
}

// ═══════════════════════════════════════════════════════════════
// SEED
// ═══════════════════════════════════════════════════════════════
function seedAll() {
  const sh = createShader(VERT_SRC, SEED_FRAG);
  for (let i = 0; i < NUM_LAYERS; i++) {
    seedBuf(buffers[i].a, sh);
    seedBuf(buffers[i].b, sh);
    buffers[i].which = 0;
  }
  frameCount_ = 0;
}
function seedBuf(fb, sh) {
  fb.begin(); shader(sh); quad(-1,-1, 1,-1, 1,1, -1,1); fb.end();
}

// ═══════════════════════════════════════════════════════════════
// SHADER REBUILD
// ═══════════════════════════════════════════════════════════════
function rebuildPhysicsShader(customGlsl) {
  const glsl = customGlsl !== undefined
    ? customGlsl
    : PHYSICS_VARIANTS[activeVariantKey].glsl;
  physShader = createShader(VERT_SRC, buildPhysicsFrag(glsl));
  if (customGlsl === undefined) {
    const d = PHYSICS_VARIANTS[activeVariantKey].defaults;
    PARAMS.c2 = d.c2; PARAMS.resistance = d.resistance;
    PARAMS.ambient = d.ambient; PARAMS.coupling = d.coupling;
  }
}

// ═══════════════════════════════════════════════════════════════
// DRAW
// ═══════════════════════════════════════════════════════════════
function draw() {
  const t = millis() * 0.001;

  const mxUV = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width  * SIM_W;
  const myUV = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height * SIM_H;
  mouseVelX  = (mxUV - pmouseUV.x) / SIM_W;
  mouseVelY  = (myUV - pmouseUV.y) / SIM_H;
  mouseSpeed = min(sqrt(mouseVelX*mouseVelX + mouseVelY*mouseVelY), 0.05);
  pmouseUV   = { x: mxUV, y: myUV };

  const mz = ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) ? 1.5
           : ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0 && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < width && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height) ? 1.0 : 0.0;

  // Physics
  for (let i = 0; i < NUM_LAYERS; i++) {
    const buf   = buffers[i];
    const read  = buf.which === 0 ? buf.a : buf.b;
    const write = buf.which === 0 ? buf.b : buf.a;
    const aboveBuf  = buffers[i === 0 ? 0 : i - 1];
    const aboveRead = aboveBuf.which === 0 ? aboveBuf.a : aboveBuf.b;

    write.begin();
    shader(physShader);
    physShader.setUniform('uField',      read.color);
    physShader.setUniform('uAbove',      aboveRead.color);
    physShader.setUniform('uRes',        [SIM_W, SIM_H]);
    physShader.setUniform('uMouse',      [mxUV, myUV, mz]);
    physShader.setUniform('uMouseVel',   [mouseVelX, mouseVelY, mouseSpeed]);
    physShader.setUniform('uTime',       t);
    physShader.setUniform('uDepth',      LAYER_DEPTH[i]);
    physShader.setUniform('uCoupling',   LAYER_COUPLING[i] * PARAMS.coupling);
    physShader.setUniform('uDamping',    LAYER_DAMPING[i]);
    physShader.setUniform('uAmbient',    LAYER_AMBIENT[i] * PARAMS.ambient);
    physShader.setUniform('uC2',         PARAMS.c2);
    physShader.setUniform('uResistance', PARAMS.resistance);
    physShader.setUniform('uIsTop',      i === 0 ? 1 : 0);
    physShader.setUniform('uFrame',      frameCount_);
    quad(-1,-1, 1,-1, 1,1, -1,1);
    write.end();
    buf.which = 1 - buf.which;
  }

  // Display
  shader(displayShader);
  for (let i = 0; i < NUM_LAYERS; i++) {
    var buf  = buffers[i];
    var read = buf.which === 0 ? buf.a : buf.b;
    displayShader.setUniform('uLayer' + i, read.color);
  }
  displayShader.setUniform('uTime', t);
  displayShader.setUniform('uRes',  [SIM_W, SIM_H]);
  quad(-1,-1, 1,-1, 1,1, -1,1);

  drawHUD();
  frameCount_++;
}

// ═══════════════════════════════════════════════════════════════
// HUD
// ═══════════════════════════════════════════════════════════════
function drawHUD() {
  resetShader();
  const v = PHYSICS_VARIANTS[activeVariantKey];

  fill(10, 16, 40, 210); noStroke();
  rect(-width/2, -height/2, width, 30);

  fill(26, 111, 255);
  textFont('monospace'); textSize(10); textAlign(LEFT, TOP);
  text('THE AGREEMENT', -width/2 + 12, -height/2 + 10);

  fill(140, 180, 255);
  text(v.name + '  ·  ' + v.tag, -width/2 + 148, -height/2 + 10);

  fill(50, 80, 120); textAlign(RIGHT, TOP);
  text(Math.round(frameRate()) + ' fps', width/2 - 12, -height/2 + 10);

  fill(10, 16, 40, 210);
  rect(-width/2, height/2 - 24, width, 24);

  fill(80, 120, 200); textAlign(LEFT, BOTTOM); textSize(9);
  text(
    'c2:' + PARAMS.c2.toFixed(3) +
    '  res:' + PARAMS.resistance.toFixed(1) +
    '  amb:' + PARAMS.ambient.toFixed(1) +
    '  coup:' + PARAMS.coupling.toFixed(1) +
    '      [ ]=c2  1-6=preset  r=reset  s=save',
    -width/2 + 12, height/2 - 6
  );
}

// ═══════════════════════════════════════════════════════════════
// KEYBOARD
// ═══════════════════════════════════════════════════════════════
function keyPressed() {
  const map = { '1':'FOUR_POINT','2':'EIGHT_POINT','3':'SPIRAL_32',
                '4':'SPIRAL_PAINT','5':'HYBRID','6':'ANISOTROPIC' };
  if (map[key]) {
    activeVariantKey = map[key];
    rebuildPhysicsShader();
    if (editorTA) {
      editorTA.value(PHYSICS_VARIANTS[activeVariantKey].glsl.trim());
      updateLineNums();
      setStatus('ok','COMPILED ✓');
    }
    refreshBtns();
    return;
  }
  if (key === '[') PARAMS.c2 = max(0.01, PARAMS.c2 - 0.02);
  if (key === ']') PARAMS.c2 = min(0.50, PARAMS.c2 + 0.02);
  if (key === 'r' || key === 'R') seedAll();
  //if (key === 's' || key === 'S') saveCanvas('agreement_' + Date.now(), '.jpg');
  if (key === 's' || key === 'S')   save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// ═══════════════════════════════════════════════════════════════
// LIVE COMPILE
// ═══════════════════════════════════════════════════════════════
function doCompile() {
  const src = editorTA.value();
  setStatus('compiling', 'COMPILING…');
  try {
    const fragSrc = buildPhysicsFrag(src);
    const gl = drawingContext;
    const fs = gl.createShader(gl.FRAGMENT_SHADER);
    gl.shaderSource(fs, fragSrc);
    gl.compileShader(fs);
    if (!gl.getShaderParameter(fs, gl.COMPILE_STATUS)) {
      const err = gl.getShaderInfoLog(fs) || 'compile error';
      setStatus('err', 'ERROR'); showErr(err); return;
    }
    physShader = createShader(VERT_SRC, fragSrc);
    setStatus('ok', 'COMPILED ✓');
    hideErr();
  } catch(e) {
    setStatus('err', 'ERROR'); showErr(e.toString());
  }
}

function setStatus(cls, txt) {
  if (!statusEl) return;
  const colors = { ok:'#40e090', err:'#ff4455', compiling:'#ffcc00' };
  statusEl.style('color', colors[cls] || '#8ab0e8');
  statusEl.html(txt);
}
function showErr(msg) {
  if (!errEl) return;
  errEl.html(msg.replace(/</g,'&lt;'));
  errEl.style('display','block');
}
function hideErr() { if (errEl) errEl.style('display','none'); }

