    </div>
  `;
  document.body.appendChild(panel);

  editorTA = select('#ed');
  statusEl = select('#status');
  errEl    = select('#errbox');

  editorTA.value(PHYSICS_VARIANTS[activeVariantKey].glsl.trim());
  updateLineNums();
  refreshBtns();

  document.getElementById('bc').onclick   = doCompile;
