    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') { e.preventDefault(); doCompile(); }
  });
}

function refreshBtns() {
  const bar = document.getElementById('pbar');
  if (!bar) return;
  bar.innerHTML = '';
  const keys = ['FOUR_POINT','EIGHT_POINT','SPIRAL_32','SPIRAL_PAINT','HYBRID','ANISOTROPIC'];
  keys.forEach(k => {
    var v = PHYSICS_VARIANTS[k];
    const b = document.createElement('button');
    b.className = 'pb' + (k === activeVariantKey ? ' on' : '');
    b.textContent = v.name;
    b.onclick = () => {
      activeVariantKey = k;
      rebuildPhysicsShader();
      if (editorTA) { editorTA.value(v.glsl.trim()); updateLineNums(); setStatus('ok','COMPILED ✓'); }
      refreshBtns();
    };
    bar.appendChild(b);
  });
}

function updateLineNums() {
  var el = document.getElementById('lnums');
  if (!el || !editorTA) return;
  const n = editorTA.value().split('\n').length;
  let h = '';
  for (let i = 1; i <= n; i++) h += i + '<br>';
  el.innerHTML = h;
}

// shaders.js
// The Agreement — Owaun Scantlebury
// All GLSL shader source stored as JS strings.
// Swap PHYSICS_VARIANTS[n] into buildPhysicsShader() to change neighbourhood.

// ═══════════════════════════════════════════════════════════════════════════
// VERTEX — shared by all passes
// ═══════════════════════════════════════════════════════════════════════════
const VERT_SRC = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main() {
  vTexCoord = aTexCoord;
  gl_Position = vec4(aPosition, 1.0);
}`;

// ═══════════════════════════════════════════════════════════════════════════
// SEED — initialise field to mid-grey (zero height)
// ═══════════════════════════════════════════════════════════════════════════
const SEED_FRAG = `
precision highp float;
varying vec2 vTexCoord;
void main() {
  gl_FragColor = vec4(0.5, 0.5, 0.0, 1.0);
}`;

// ═══════════════════════════════════════════════════════════════════════════
// PHYSICS NEIGHBOURHOODS
// Each entry is a GLSL snippet that reads from uField and produces float lap.
// Injected into buildPhysicsShader().
// ═══════════════════════════════════════════════════════════════════════════
const PHYSICS_VARIANTS = {

  // ── Classic 4-point cardinal ─────────────────────────────────────────────
  FOUR_POINT: {
    name:      '4-Point Cardinal',
    tag:       'classic · stable',
    stability: 92,
    defaults:  { c2: 0.25, damping: 0.997, resistance: 6.0, ambient: 1.0, coupling: 1.0 },
    glsl: `
  float hN = unpackH(texture2D(uField, uv + vec2(0.0,  tex.y)).r);
  float hS = unpackH(texture2D(uField, uv - vec2(0.0,  tex.y)).r);
  float hE = unpackH(texture2D(uField, uv + vec2(tex.x, 0.0 )).r);
  float hW = unpackH(texture2D(uField, uv - vec2(tex.x, 0.0 )).r);
  float lap = hN + hS + hE + hW - 4.0 * hCur;`
  },

  // ── 8-point including diagonals ──────────────────────────────────────────
  EIGHT_POINT: {
    name:      '8-Point',
    tag:       'smoother · isotropic',
    stability: 82,
    defaults:  { c2: 0.18, damping: 0.997, resistance: 5.0, ambient: 1.0, coupling: 1.0 },
    glsl: `
  float hN  = unpackH(texture2D(uField, uv + vec2( 0.0,  tex.y)).r);
  float hS  = unpackH(texture2D(uField, uv + vec2( 0.0, -tex.y)).r);
  float hE  = unpackH(texture2D(uField, uv + vec2( tex.x, 0.0 )).r);
  float hW  = unpackH(texture2D(uField, uv + vec2(-tex.x, 0.0 )).r);
  float hNE = unpackH(texture2D(uField, uv + vec2( tex.x,  tex.y)).r);
  float hNW = unpackH(texture2D(uField, uv + vec2(-tex.x,  tex.y)).r);
  float hSE = unpackH(texture2D(uField, uv + vec2( tex.x, -tex.y)).r);
  float hSW = unpackH(texture2D(uField, uv + vec2(-tex.x, -tex.y)).r);
  float lap = (hN + hS + hE + hW) * 0.5
            + (hNE + hNW + hSE + hSW) * 0.25
            - 3.0 * hCur;`
  },

  // ── 32-point Fibonacci spiral ────────────────────────────────────────────
  SPIRAL_32: {
    name:      'Spiral 32',
    tag:       'fibonacci · organic',
    stability: 70,
    defaults:  { c2: 0.12, damping: 0.997, resistance: 2.0, ambient: 1.5, coupling: 0.8 },
    glsl: `
  float total = 0.0;
  float ga    = 2.39996; // golden angle
  for (float i = 1.0; i <= 32.0; i++) {
    float r   = sqrt(i) * 1.5;
    float th  = i * ga;
    vec2  off = vec2(cos(th), sin(th)) * tex * r;
    total += unpackH(texture2D(uField, uv + off).r);
  }
  float lap = (total / 32.0) - hCur;`
  },

  // ── Spiral 32 — paint / sculptural mode (c2=0.05) ───────────────────────
  SPIRAL_PAINT: {
    name:      'Spiral Paint',
    tag:       'c2=0.05 · glass coral',
    stability: 99,
    defaults:  { c2: 0.05, damping: 0.9985, resistance: 2.0, ambient: 1.5, coupling: 0.6 },
    glsl: `
  float total = 0.0;
  float ga    = 2.39996;
  for (float i = 1.0; i <= 32.0; i++) {
    float r   = sqrt(i) * 1.5;
    float th  = i * ga;
    vec2  off = vec2(cos(th), sin(th)) * tex * r;
    total += unpackH(texture2D(uField, uv + off).r);
  }
  float lap = (total / 32.0) - hCur;`
  },

  // ── Hybrid: 4-point + spiral blended ────────────────────────────────────
  HYBRID: {
    name:      'Hybrid 4+Spiral',
    tag:       'blended · best of both',
    stability: 76,
    defaults:  { c2: 0.20, damping: 0.997, resistance: 3.5, ambient: 1.2, coupling: 0.9 },
    glsl: `
  float hN = unpackH(texture2D(uField, uv + vec2( 0.0,  tex.y)).r);
  float hS = unpackH(texture2D(uField, uv + vec2( 0.0, -tex.y)).r);
  float hE = unpackH(texture2D(uField, uv + vec2( tex.x, 0.0 )).r);
  float hW = unpackH(texture2D(uField, uv + vec2(-tex.x, 0.0 )).r);
  float lap4 = hN + hS + hE + hW - 4.0 * hCur;
  float total = 0.0; float ga = 2.39996;
  for (float i = 1.0; i <= 32.0; i++) {
    float r = sqrt(i) * 1.5; float th = i * ga;
    vec2 off = vec2(cos(th), sin(th)) * tex * r;
    total += unpackH(texture2D(uField, uv + off).r);
  }
  float lap32 = (total / 32.0) - hCur;
  float blend = 0.5; // 0 = pure 4pt, 1 = pure spiral
  float lap   = mix(lap4, lap32, blend);`
  },

  // ── Anisotropic: different H/V wave speeds ───────────────────────────────
  ANISOTROPIC: {
    name:      'Anisotropic',
    tag:       'directional · striped',
    stability: 80,
    defaults:  { c2: 0.30, damping: 0.997, resistance: 4.0, ambient: 1.0, coupling: 1.0 },
    glsl: `
  float hN = unpackH(texture2D(uField, uv + vec2( 0.0,  tex.y)).r);
  float hS = unpackH(texture2D(uField, uv + vec2( 0.0, -tex.y)).r);
  float hE = unpackH(texture2D(uField, uv + vec2( tex.x, 0.0 )).r);
  float hW = unpackH(texture2D(uField, uv + vec2(-tex.x, 0.0 )).r);
  float cH  = 0.40; // horizontal speed — edit this
  float cV  = 0.20; // vertical speed   — edit this
  float lap = (hE + hW - 2.0 * hCur) * cH
            + (hN + hS - 2.0 * hCur) * cV;`
  },

};

// ═══════════════════════════════════════════════════════════════════════════
// PHYSICS SHADER BUILDER
// Injects a neighbourhood snippet into the full wave equation.
// ═══════════════════════════════════════════════════════════════════════════
function buildPhysicsFrag(neighbourhoodGLSL) {
  return `
precision highp float;
varying vec2 vTexCoord;

uniform sampler2D uField;    // current physics state (R=hCur, G=hPrev, B=energy)
uniform sampler2D uAbove;    // layer above (for vertical coupling)
uniform vec2  uRes;
uniform vec3  uMouse;        // xy = pixel pos, z = strength (0=none 1=move 1.5=held)
uniform vec3  uMouseVel;     // xy = delta, z = speed
uniform float uTime;
uniform float uDepth;        // 0=surface, 1=abyss
uniform float uCoupling;     // vertical coupling strength
uniform float uDamping;      // per-frame energy retention
uniform float uAmbient;      // ambient thermal breath multiplier
uniform float uC2;           // wave speed squared — THE key parameter
uniform float uResistance;   // velocity-proportional drag
uniform int   uIsTop;        // 1 if this is the surface layer
uniform int   uFrame;

float unpackH(float r) { return r * 2.0 - 1.0; }
float packH(float h)   { return clamp(h * 0.5 + 0.5, 0.0, 1.0); }

void main() {
  vec2 uv  = vTexCoord;
  vec2 tex = 1.0 / uRes;

  // ── MEMORY ─────────────────────────────────────────────────────
  vec4  state  = texture2D(uField, uv);
  float hCur   = unpackH(state.r);
  float hPrev  = unpackH(state.g);
  float energy = state.b;

  // ── NEGOTIATION (neighbourhood) ─────────────────────────────────
  ${neighbourhoodGLSL}

  // ── VERTICAL COUPLING ───────────────────────────────────────────
  float hAbove   = unpackH(texture2D(uAbove, uv).r);
  float vertPush = (hAbove - hCur) * uCoupling;

  // ── RESISTANCE ──────────────────────────────────────────────────
  float velocity   = hCur - hPrev;
  float resistance = 1.0 / (1.0 + abs(velocity) * uResistance);

  // ── PURPOSE — wave equation ──────────────────────────────────────
  float hNext = (2.0 * hCur - hPrev + (lap * uC2 + vertPush)) * resistance;
  hNext *= uDamping;

  // ── AMBIENT THERMAL BREATH ───────────────────────────────────────
  hNext += sin(uv.x * 3.14159 * 4.0 + uTime * (0.3 + uDepth * 0.4)) *
           sin(uv.y * 3.14159 * 3.7 + uTime * (0.2 + uDepth * 0.3)) * uAmbient * 0.003;
  hNext += sin(uv.x * 3.14159 * 9.1 + uTime * 0.17) *
           sin(uv.y * 3.14159 * 7.3 + uTime * 0.23) * uAmbient * 0.001;

  // ── SEED on startup ──────────────────────────────────────────────
  if (uIsTop == 1 && uFrame < 6) {
    float d = length(uv - vec2(0.5));
    hNext += exp(-d * d * 200.0) * 1.5;
  }

  // ── MOUSE INPUT ──────────────────────────────────────────────────
  if (uIsTop == 1 && uMouse.z >= 1.0) {
    vec2  mUV     = vec2(uMouse.x / uRes.x, 1.0 - uMouse.y / uRes.y);
    vec2  diff    = uv - mUV;
    float dist    = length(diff);
    float gaussian = exp(-dist * dist * 150.0);
    float str;
    if (uMouse.z >= 1.5) {
      str = 1.2;
    } else {
      float speed = uMouseVel.z;
      if (speed > 0.001) {
        vec2  velDir = uMouseVel.xy / speed;
        float ahead  = dot(normalize(diff), velDir);
        str = mix(0.15, 0.9, clamp(ahead * 0.5 + 0.5, 0.0, 1.0));
        str *= clamp(speed * 80.0, 0.3, 1.2);
      } else {
        str = 0.4;
      }
    }
    hNext += gaussian * str;
  }

  // ── PACK ─────────────────────────────────────────────────────────
  float newB = clamp(energy * 0.995 + abs(hNext) * 0.08, 0.0, 1.0);
  gl_FragColor = vec4(packH(hNext), packH(hCur), newB, 1.0);
}`;
}

// ═══════════════════════════════════════════════════════════════════════════
// DISPLAY SHADER
// Reads all 8 physics layers, composites to screen.
// ═══════════════════════════════════════════════════════════════════════════
const DISPLAY_FRAG = `
precision highp float;
varying vec2 vTexCoord;

// Only the surface layer (layer 0) is used for display.
// Matches display_water.glsl exactly.
uniform sampler2D uLayer0;
uniform sampler2D uLayer1;
uniform sampler2D uLayer2;
uniform sampler2D uLayer3;
uniform sampler2D uLayer4;
uniform sampler2D uLayer5;
uniform sampler2D uLayer6;
uniform sampler2D uLayer7;
uniform float uTime;
uniform vec2  uRes;

void main() {
  vec2 uv    = vTexCoord;
  vec2 texel = 1.0 / uRes;

  vec4  state  = texture2D(uLayer0, uv);
  float hCur   = state.r * 2.0 - 1.0;
  float hPrev  = state.g * 2.0 - 1.0;
  float energy = state.b;
  float velocity = hCur - hPrev;

  // Surface normal from neighbours
  float hE = texture2D(uLayer0, uv + vec2( texel.x,  0.0)).r * 2.0 - 1.0;
  float hW = texture2D(uLayer0, uv + vec2(-texel.x,  0.0)).r * 2.0 - 1.0;
  float hN = texture2D(uLayer0, uv + vec2( 0.0,  texel.y)).r * 2.0 - 1.0;
  float hS = texture2D(uLayer0, uv + vec2( 0.0, -texel.y)).r * 2.0 - 1.0;
  vec3 normal = normalize(vec3(hW - hE, hS - hN, 0.08));

  // Lighting
  vec3  sunDir  = normalize(vec3(0.6, 0.8, 1.0));
  vec3  skyDir  = normalize(vec3(-0.3, -0.5, 1.0));
  float sunDiff = max(dot(normal, sunDir), 0.0);
  float skyDiff = max(dot(normal, skyDir), 0.0) * 0.3;
  float diffuse = sunDiff + skyDiff;

  // Specular
  vec3  viewDir = vec3(0.0, 0.0, 1.0);
  vec3  halfDir = normalize(sunDir + viewDir);
  float specular = pow(max(dot(normal, halfDir), 0.0), 120.0) * 1.8;

  // Base water colour
  vec3  deepCol    = vec3(0.01, 0.05, 0.15);
  vec3  shallowCol = vec3(0.04, 0.18, 0.32);
  float depth      = clamp(hCur * 0.5 + 0.5, 0.0, 1.0);
  vec3  waterCol   = mix(deepCol, shallowCol, depth);
  waterCol        *= 0.4 + diffuse * 0.8;

  // Crest brightness
  float crest = clamp(hCur * 3.0, 0.0, 1.0);
  waterCol += vec3(0.55, 0.78, 0.95) * crest * sunDiff * 0.7;

  // Specular sun glint
  waterCol += vec3(1.0, 0.97, 0.92) * specular;

  // Energy memory glow — cyan
  waterCol += vec3(0.05, 0.35, 0.55) * energy * energy * 0.8;

  // Velocity colour temperature
  waterCol += vec3(0.08, 0.04, -0.02) * velocity * 3.0;

  // Foam at high velocity
  float foam = clamp(abs(velocity) * 8.0 - 0.3, 0.0, 1.0);
  waterCol = mix(waterCol, vec3(0.85, 0.92, 1.0), foam * 0.6);

  // Edge — deep water horizon
  vec2  edge     = abs(uv - 0.5) * 2.0;
  float edgeDist = max(edge.x, edge.y);
  float edgeFade = smoothstep(0.7, 1.0, edgeDist);
  waterCol = mix(waterCol, deepCol * 0.3, edgeFade);

  vec3 col = clamp(waterCol, 0.0, 1.0);

  // vignette
  float v = length(uv - 0.5) * 1.7;
  col *= 1.0 - v * v * 0.75;

  gl_FragColor = vec4(col, 1.0);
}`;

